import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { MessageService } from 'primeng/api';
import { AdminUserService } from '../../../../../../libs/openapi/src/api/admin-user.service';

@Component({
  selector: 'app-user-form',
  templateUrl: './user-form.component.html',
  styleUrls: ['./user-form.component.scss'],
})
export class UserFormComponent implements OnInit {
  userForm: FormGroup;
  isEditMode = false;
  userId: string | null = null;
  loading = false;

  constructor(
    private fb: FormBuilder,
    private route: ActivatedRoute,
    private router: Router,
    private userService: AdminUserService,
    private messageService: MessageService
  ) {
    this.userForm = this.fb.group({
      name: ['', [Validators.required, Validators.minLength(2)]],
      email: [
        { value: '', disabled: true },
        [Validators.required, Validators.email],
      ],
      phone: [''],
      address: [''],
      isActive: [true],
    });
  }

  ngOnInit(): void {
    this.userId = this.route.snapshot.params['id'];
    if (this.userId) {
      this.isEditMode = true;
      this.loadUserData(this.userId);
    } else {
      this.isEditMode = false;
      this.userForm.patchValue({
        isActive: true,
      });
      this.userForm.get('email')?.enable();
    }
  }

  loadUserData(id: string) {
    this.loading = true;
    this.userService.apiAdminUserIdGet(id).subscribe({
      next: (response: any) => {
        this.userForm.patchValue({
          name: response.data.name,
          email: response.data.email,
          phone: response.data.phone,
          address: response.data.address,
          isActive: response.data.isActive,
        });
        this.loading = false;
      },
      error: () => {
        this.messageService.add({
          severity: 'error',
          summary: '錯誤',
          detail: '無法載入使用者資料',
        });
        this.loading = false;
      },
    });
  }

  onSubmit() {
    if (this.userForm.valid) {
      this.loading = true;
      const userData = {
        name: this.userForm.get('name')?.value,
        email: this.userForm.get('email')?.value,
        phone: this.userForm.get('phone')?.value,
        address: this.userForm.get('address')?.value,
        isActive: this.userForm.get('isActive')?.value,
      };

      if (this.isEditMode && this.userId) {
        this.userService.apiAdminUserIdPut(this.userId, userData).subscribe({
          next: () => {
            this.messageService.add({
              severity: 'success',
              summary: '成功',
              detail: '使用者更新成功',
            });
            this.router.navigate(['/users']);
          },
          error: () => {
            this.messageService.add({
              severity: 'error',
              summary: '錯誤',
              detail: '使用者更新失敗',
            });
            this.loading = false;
          },
        });
      } else {
        this.userService.apiAdminUserPost(userData).subscribe({
          next: () => {
            this.messageService.add({
              severity: 'success',
              summary: '成功',
              detail: '使用者新增成功',
            });
            this.router.navigate(['/users']);
          },
          error: () => {
            this.messageService.add({
              severity: 'error',
              summary: '錯誤',
              detail: '使用者新增失敗',
            });
            this.loading = false;
          },
        });
      }
    }
  }
}
